                match self.group_member(&peer.public()) {
                    Ok(true) => {}
                    Ok(false) => continue,
                    Err(error) => {
                        self.observe_mailbox_work(
                            super::work_observation::reason::DRAIN_GROUP_LOOKUP_FAILED,
                            None,
