    policy: NetworkPolicy,
    membership: NetworkMembership,
}

impl RelayNetwork {
    pub fn new(
        policy: NetworkPolicy,
        membership: NetworkMembership,
        own: &PublicIdentity,
        now: u64,
    ) -> Result<Self, String> {
        membership.verify(&policy, own, now)?;
        Ok(Self { policy, membership })
    }

