            }
            if !self.quiet_control_proof_current(&proof.controls, &proof.recipient)? {
                return Ok(false);
            }
            let current = self
                .sync_store(&proof.recipient)
                .lock()
                .expect("projection")
                .history_sync_stamp(&proof.conversation)?;
            if current.as_ref() != Some(&proof.local) {
                return Ok(false);
            }
        }
        Ok(!proofs.is_empty())
    }

