    async fn opaque_mailbox_round_confirmed_observing<IO>(
        &self,
        channel: &mut crate::transport::SecureChannel<IO>,
        recipient: &PublicIdentity,
        conversation: Option<ConversationId>,
        mailbox: RelayMailbox,
        confirm: Option<EventId>,
        intent: MailboxIntent,
        observe: bool,
    ) -> Result<PublicationRound, super::session::SessionError>
    where
        IO: AsyncRead + AsyncWrite + Unpin,
    {
        let privacy = self.privacy.generation.load(Ordering::SeqCst);
        let bridge = self.bridge_generation.load(Ordering::SeqCst);
        let mut progress = match intent {
            MailboxIntent::Duplex => OpaqueMailboxProgress::new(
                channel.peer_identity(),
                recipient,
                conversation,
                mailbox,
            ),
            MailboxIntent::HistoryPublication => OpaqueMailboxProgress::new_history_publication(
                channel.peer_identity(),
                recipient,
                conversation.ok_or(super::session::SessionError::UnexpectedMessage)?,
                mailbox,
            ),
            MailboxIntent::FileDispatch => OpaqueMailboxProgress::new_file_dispatch(
                channel.peer_identity(),
                recipient,
                conversation.ok_or(super::session::SessionError::UnexpectedMessage)?,
                mailbox,
            ),
        };
        while !self.advance_opaque_mailbox(channel, &mut progress).await? {}
        if let Some(inner) = confirm {
            if !channel.io_admitted() {
                return Err(super::session::SessionError::UnexpectedMessage);
            }
            let relay = progress.relay.clone();
            let relay = progress.relay.clone();
            let federated = RelayMailbox::is_federated_id(&progress.mailbox.id());
            let privacy = self.privacy.generation.load(Ordering::SeqCst);
            let bridge = self.bridge_generation.load(Ordering::SeqCst);
            let current = || {
                self.relay_send_allowed(&relay)
                    && self.privacy.generation.load(Ordering::SeqCst) == privacy
                    && (!federated
                        || (self.bridge_directory_allowed()
                            && self.bridge_generation.load(Ordering::SeqCst) == bridge))
            };
            let modern_publication = intent == MailboxIntent::HistoryPublication
                && matches!(progress.incremental, incremental::Mode::Active(_));
            let source = if modern_publication {
                let conversation = progress.conversation.ok_or(LogError::StaleCursor)?;
                let owner = self.sync_store(&progress.recipient);
                let stamp = owner
                    .lock()
                    .expect("projection")
                    .history_sync_stamp(&conversation)?
                    .ok_or(LogError::StaleCursor)?;
                Some(stamp)
            } else {
                None
            };
            let outer = self
                .resolve_opaque_confirmation(&mut progress, inner, &current)
                .await?;
            let outer = if modern_publication {
                match outer {
                    Some(outer) => Some(
                        self.ensure_opaque_confirmation_custody(
                            channel,
                            &mut progress,
                            (inner, outer),
                            source.as_ref().ok_or(LogError::StaleCursor)?,
                            &current,
                        )
                        .await?,
                    ),
                    None => {
                        progress.uploaded.retain(|(id, _)| *id != inner);
                        None
                    }
                }
            } else {
                outer
            };
            if !current() || !channel.io_admitted() {
                return Err(super::session::SessionError::UnexpectedMessage);
            }
            if let Some(outer) = outer
                && !progress.uploaded.contains(&(inner, outer))
            {
                if progress.uploaded.len() >= 64 {
                    progress.uploaded.remove(0);
                }
                progress.uploaded.push((inner, outer));
            }
        }
        let local = if observe
            && confirm.is_none()
            && channel.io_admitted()
            && channel.peer_identity() == &progress.relay
        {
            self.qualified_unchanged_publication(&progress)?
        } else {
            None
        };
        let proofs = local
            .into_iter()
            .map(|(local, controls)| PublicationProof {
                recipient: progress.recipient.clone(),
                relay: progress.relay.clone(),
                conversation: progress.conversation.expect("qualified history"),
                local,
                controls,
                privacy,
                bridge,
                federated: RelayMailbox::is_federated_id(&progress.mailbox.id()),
            })
            .collect::<Vec<_>>();
        let quiet = !proofs.is_empty() && self.publication_proofs_current(&proofs)?;
        Ok(PublicationRound {
            selected: progress.uploaded,
            quiet,
            proofs,
        })
    }

