new='''    /// Capture the existing history owner's source/policy stamp without custody
    /// documents: publishing our own witness must not restart recipient progress.
    async fn observe_channel_relay_input(self: &Arc<Self>, channel: ConversationId)
        -> Result<Option<[u8; 32]>, LogError>
    {
        let retired = || LogError::AdmissionRejected("participant runtime retired".into());
        let capacity = self.runtime_work.local_repair_capacity().await.ok_or_else(retired)?;
        let work = self.runtime_work.admit().ok_or_else(retired)?;
        let node = self.clone();
        work.spawn_local_repair_blocking(capacity, move || {
            use sha2::{Digest, Sha256};
            use std::sync::atomic::Ordering;
            // This self stamp is only a global scheduling fence, never peer
            // authorization. The real recipient must qualify its own publication.
            let stamp = node.sync_store(&node.identity.public()).lock().expect("projection")
                .history_sync_stamp(&channel)?;
            let Some(stamp) = stamp else { return Ok(None) };
            let roster = node.roster.lock().expect("roster").metadata_digest()?;
            let (routes, _) = node.channel_control_route_input(&mut HashMap::new());
            let bytes = bincode::serialize(&(
                stamp, roster, routes,
                node.bridge_generation.load(Ordering::Acquire),
                node.post_office_enabled.load(Ordering::Acquire),
                node.post_office_send_enabled.load(Ordering::Acquire),
                node.delivery_suspended.load(Ordering::Acquire),
            )).map_err(|error| LogError::Serialization(error.to_string()))?;
            Ok(Some(Sha256::digest(bytes).into()))
        }).await.map_err(|error| LogError::Io(std::io::Error::other(error)))?.into_inner()
    }

    /// One recipient and one exact witness per existing recovery turn. Full
    /// publication completion parks scheduling; it never increments member copies.
    async fn retry_channel_relay_turn(
        self: &Arc<Self>, cursor: usize,
        cursors: &mut HashMap<ConversationId, CustodyRetryCursor>,
    ) -> bool {
        let result: Result<bool, NodeError> = Box::pin(async {
            let mut channels = self.channels.lock().expect("channels").channel_ids();
            channels.sort_unstable_by_key(|id| *id.as_bytes());
            if channels.is_empty() { return Ok(false); }
            let channel = channels[cursor % channels.len()];
            let mut recipients = self.channel_custody_repair_members(channel);
            recipients.retain(|recipient| self.channel_custody_member_principal(channel, recipient, None).is_some());
            recipients.sort_unstable_by_key(|recipient| (recipient.ed25519_pub, recipient.x25519_pub));
            recipients.dedup();
            let relays_available = {
                let roster = self.roster.lock().expect("roster");
                self.post_office_candidates(&roster)
            }.into_iter().any(|relay| self.relay_send_allowed(&relay.public));
            let state = &mut cursors.entry(channel).or_default().relay;
            if recipients.is_empty() || !relays_available {
                state.complete = true;
                return Ok(false);
            }
            let Some(input) = self.observe_channel_relay_input(channel).await? else { return Ok(false) };
            if state.input != Some(input) {
                state.input = Some(input);
                state.remaining = recipients.len();
                state.failed = false;
                state.complete = false;
                state.retry_at = None;
                state.backoff.reset();
                // Preserve position across invalidation: frequent source changes
                // cannot repeatedly serve only the first recipient.
            }
            if state.complete || state.retry_at.is_some_and(|at| at > tokio::time::Instant::now()) {
                return Ok(false);
            }
            let author = crate::eventlog::Author::from_ed25519(self.identity.public().ed25519_pub);
            let witness = self.log.lock().expect("log").message_keys_after(channel, author, None, 1)?
                .first().map(|(_, id)| *id);
            let Some(witness) = witness else { state.complete = true; return Ok(false) };
            let recipient = recipients.iter().find(|recipient| state.after.is_none_or(|after|
                (recipient.ed25519_pub, recipient.x25519_pub) > after)).unwrap_or(&recipients[0]).clone();
            state.after = Some((recipient.ed25519_pub, recipient.x25519_pub));
            let candidates = {
                let roster = self.roster.lock().expect("roster");
                self.post_office_candidates_for(&roster, &recipient)
            };
            let relay = candidates.into_iter().find(|relay| self.relay_send_allowed(&relay.public));
            let node = self.clone();
            let attempt = Box::pin(async {
                let relay = relay.ok_or(NodeError::Authorization("relay unavailable".into()))?;
                if node.channel_custody_member_principal(channel, &recipient, None).is_none() {
                    return Ok::<_, NodeError>(false);
                }
                let mut connection = node.privacy_sync_dial(relay.addr, &relay.public).await
                    .map_err(|error| NodeError::Channel(error.to_string()))?;
                if !node.relay_send_allowed(&relay.public)
                    || node.channel_custody_member_principal(channel, &recipient, None).is_none()
                { return Ok(false); }
                let qualified = node.repair_channel_relay_publication(&mut connection, &recipient, channel, witness).await
                    .map_err(|error| NodeError::Channel(error.to_string()))?;
                let current = node.relay_send_allowed(&relay.public)
                    && node.channel_custody_member_principal(channel, &recipient, None).is_some();
                if qualified && current { node.recycle_sync_channel(connection); }
                Ok(qualified && current)
            });
            let qualified = matches!(tokio::time::timeout(super::delivery_runtime::RELAY_EXCHANGE_TIMEOUT, attempt).await, Ok(Ok(true)))
                && self.observe_channel_relay_input(channel).await? == Some(input);
            state.failed |= !qualified;
            state.remaining = state.remaining.saturating_sub(1);
            if state.remaining == 0 {
                state.complete = !state.failed;
                state.remaining = recipients.len();
                state.retry_at = Some(tokio::time::Instant::now() + if state.complete {
                    CHANNEL_CUSTODY_QUIET_INTERVAL
                } else { state.backoff.next_delay_capped(0, CHANNEL_CUSTODY_QUIET_INTERVAL) });
                state.failed = false;
            }
            Ok(true)
        }).await;
        match result {
            Ok(attempted) => attempted,
            Err(error) => { log::warn!("channel relay repair deferred: {error}"); false }
        }
    }

