async fn accepted_channel_recovers_relay_custody_after_initial_handshake_failure() {
    use crate::node::test_support::{IndependentPeerRuntime, node_with_files};
    use crate::postoffice::{
        IndexedPostOffice, federation::IndexedRelayEndpoint, opaque::RelayMailbox,
    };
    use crate::storage::profile::ProfileStorageLease;
    use futures_util::FutureExt;
