    pub(in crate::node) async fn repair_channel_relay_publication(
        &self,
        channel: &mut crate::transport::SecureChannel<tokio::net::TcpStream>,
        recipient: &PublicIdentity,
        conversation: ConversationId,
        event: EventId,
    ) -> Result<bool, super::session::SessionError> {
        let privacy = self.privacy.generation.load(Ordering::Acquire);
        let bridge = self.bridge_generation.load(Ordering::Acquire);
        let relay = channel.peer_identity().clone();
        let current = || {
            self.relay_send_allowed(&relay)
                && self.privacy.generation.load(Ordering::Acquire) == privacy
                && self.bridge_generation.load(Ordering::Acquire) == bridge
                && self
                    .channel_custody_member_principal(conversation, recipient, None)
                    .is_some()
        };
        if !current() {
            return Ok(false);
        }
        let result = self
            .opaque_relay_round_with_intent_observing(
                channel,
                recipient,
                Some(conversation),
                Some(event),
                MailboxIntent::HistoryPublication,
                true,
            )
            .await?;
        let qualified = result.quiet && self.publication_proofs_current(&result.proofs)?;
        if !current() {
            return Ok(false);
        }
        if !result.selected.iter().any(|(inner, _)| *inner == event) {
            // Modern confirmation positively resolves an unselected target.
            // An obsolete/expired witness cannot prevent a full publication
            // from parking; this publishes no custody fact for that target.
            return Ok(qualified);
        }
        let mut mailboxes = vec![
            RelayMailbox::new(&self.identity, recipient, channel.peer_identity())
                .map_err(|error| super::session::SessionError::Serialization(error.to_string()))?,
        ];
        if self.bridge_directory_allowed() {
            mailboxes.push(
                RelayMailbox::federated(&self.identity, recipient).map_err(|error| {
                    super::session::SessionError::Serialization(error.to_string())
                })?,
            );
        }
        let mut held = false;
        for (_, outer) in result.selected.iter().filter(|(inner, _)| *inner == event) {
            for mailbox in &mailboxes {
                if super::session::request_durable_have(channel, mailbox.id(), *outer).await? {
                    held = true;
                    break;
                }
            }
            if held {
                break;
            }
        }
        if !held || !current() {
            return Ok(false);
        }
        // Legacy endpoints can establish this exact custody even without a
        // modern full-publication proof; their scheduling remains deferred.
        self.publish_channel_custody(
            conversation,
            event,
            channel.peer_identity(),
            true,
            false,
            true,
        )

