#[derive(Clone, Copy, PartialEq, Eq)]
enum ChannelRelayRecoveryScenario {
    InitialFailure,
    PartialRecipients,
    Policy,
    StalledInitial,
    Cancellation,
    ControlMutation,
}

#[tokio::test]
async fn channel_relay_completion_rejects_concurrent_local_control_change() {
    Box::pin(channel_relay_recovery(
        ChannelRelayRecoveryScenario::ControlMutation,
    ))
    .await;
}

#[tokio::test]
async fn accepted_channel_recovers_relay_custody_after_initial_handshake_failure() {
    Box::pin(channel_relay_recovery(
        ChannelRelayRecoveryScenario::InitialFailure,
    ))
    .await;
}

#[tokio::test]
async fn channel_relay_recovery_qualifies_each_recipient_and_settles() {
    Box::pin(channel_relay_recovery(
        ChannelRelayRecoveryScenario::PartialRecipients,
    ))
    .await;
}

#[tokio::test]
async fn channel_relay_recovery_respects_permission_and_reenable() {
    Box::pin(channel_relay_recovery(ChannelRelayRecoveryScenario::Policy)).await;
}

#[tokio::test]
async fn stalled_initial_channel_relay_flush_leaves_recoverable_acceptance() {
    Box::pin(channel_relay_recovery(
        ChannelRelayRecoveryScenario::StalledInitial,
    ))
    .await;
}

